// ProcessLog filters by depositEventSignature (topics[0]) — Layer 1
// ProcessDepositLog deduplicates by sequential merkle index — Layer 2
// CRITICAL: processingLock is only acquired as RLock, never WLock
// s.lastReceivedMerkleIndex = index (write under RLock!)
// ProcessDepositRequests (EIP-6110) has NO per-request index deduplication

func UnpackDepositLogData(data []byte) (pubkey, withdrawalCredentials, amount, signature, index []byte, err error) {
    reader := bytes.NewReader([]byte(DepositContractABI))
    contractAbi, err := abi.JSON(reader)
    unpackedLogs, err := contractAbi.Unpack("DepositEvent", data)
    return unpackedLogs[0].([]byte), unpackedLogs[1].([]byte), unpackedLogs[2].([]byte), unpackedLogs[3].([]byte), unpackedLogs[4].([]byte), nil
}

func (s *Service) notifyNewPayload(...) (bool, error) {
    var requests *enginev1.ExecutionRequests
    if blk.Version() >= version.Electra {
        requests, err = blk.Block().Body().ExecutionRequests()
        if requests == nil {
            return false, errors.New("nil execution requests")
        }
    }
    lastValidHash, err = s.cfg.ExecutionEngineCaller.NewPayload(ctx, payload, versionedHashes, parentRoot, requests)
    // RequestsHash computed by EL via engine_newPayloadV4 — EncodeExecutionRequests serializes in fixed iota order
}
